B.aP3=s(["CREATE TABLE auth_users (\n    id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE,\n    display_name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','member','reader')),\n    password_salt TEXT NOT NULL, password_hash TEXT NOT NULL, password_iterations INTEGER NOT NULL,\n    active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), failed_attempts INTEGER NOT NULL DEFAULT 0, lock_until TEXT, created_at TEXT NOT NULL)","CREATE TABLE auth_memberships (user_id TEXT NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE,\n    enterprise_id TEXT NOT NULL REFERENCES enterprises(id) ON DELETE CASCADE,\n    PRIMARY KEY(user_id,enterprise_id))","CREATE TABLE auth_sessions (token_hash TEXT PRIMARY KEY,\n    user_id TEXT NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE,\n    created_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0)","CREATE INDEX auth_sessions_user ON auth_sessions(user_id)","CREATE TABLE user_preferences (user_id TEXT NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE,\n    key TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY(user_id,key))","CREATE TABLE tech_manufacturers (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE)","CREATE TABLE tech_types (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE)","CREATE TABLE tech_ranges (id TEXT PRIMARY KEY, manufacturer_id TEXT NOT NULL REFERENCES tech_manufacturers(id),\n    type_id TEXT NOT NULL REFERENCES tech_types(id), name TEXT NOT NULL)","CREATE INDEX tech_ranges_parent ON tech_ranges(manufacturer_id,type_id)","CREATE TABLE tech_models (id TEXT PRIMARY KEY, range_id TEXT NOT NULL REFERENCES tech_ranges(id), name TEXT NOT NULL)","CREATE INDEX tech_models_parent ON tech_models(range_id)","CREATE TABLE tech_documents (id TEXT PRIMARY KEY, manufacturer_id TEXT NOT NULL REFERENCES tech_manufacturers(id),\n    title TEXT NOT NULL, type TEXT NOT NULL DEFAULT '', reference TEXT NOT NULL DEFAULT '', version TEXT NOT NULL DEFAULT '',\n    date TEXT, origin TEXT NOT NULL, imported_at TEXT NOT NULL, local_path TEXT, sha256 TEXT, url TEXT)","CREATE TABLE tech_variants (id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES tech_models(id),\n    name TEXT NOT NULL DEFAULT '', reference TEXT NOT NULL DEFAULT '', generation TEXT NOT NULL DEFAULT '',\n    period TEXT NOT NULL DEFAULT '', year_start INTEGER, year_end INTEGER,\n    status TEXT NOT NULL DEFAULT 'unknown', energy TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '',\n    attributes TEXT NOT NULL DEFAULT '{}', source_document_id TEXT REFERENCES tech_documents(id), source_page INTEGER CHECK(source_page IS NULL OR source_page > 0), CHECK(year_start IS NULL OR year_end IS NULL OR year_end >= year_start))","CREATE INDEX tech_variants_model ON tech_variants(model_id)","CREATE INDEX tech_variants_reference ON tech_variants(reference)","CREATE TABLE tech_document_links (document_id TEXT NOT NULL REFERENCES tech_documents(id) ON DELETE CASCADE,\n    variant_id TEXT NOT NULL REFERENCES tech_variants(id) ON DELETE CASCADE, PRIMARY KEY(document_id,variant_id))","CREATE TABLE tech_faults (id TEXT PRIMARY KEY, manufacturer_id TEXT NOT NULL REFERENCES tech_manufacturers(id),\n    code TEXT NOT NULL, normalized_code TEXT NOT NULL, meaning TEXT NOT NULL,\n    description TEXT NOT NULL DEFAULT '', causes TEXT NOT NULL DEFAULT '', checks TEXT NOT NULL DEFAULT '',\n    diagnostic TEXT NOT NULL DEFAULT '', solutions TEXT NOT NULL DEFAULT '', components TEXT NOT NULL DEFAULT '',\n    control_values TEXT NOT NULL DEFAULT '', remarks TEXT NOT NULL DEFAULT '', criticality TEXT,\n    keywords TEXT NOT NULL DEFAULT '', document_id TEXT NOT NULL REFERENCES tech_documents(id), page INTEGER CHECK(page IS NULL OR page > 0))","CREATE INDEX tech_faults_code ON tech_faults(normalized_code)","CREATE INDEX tech_faults_original ON tech_faults(code)","CREATE TABLE tech_fault_contexts (fault_id TEXT NOT NULL REFERENCES tech_faults(id) ON DELETE CASCADE,\n    variant_id TEXT NOT NULL REFERENCES tech_variants(id) ON DELETE CASCADE, PRIMARY KEY(fault_id,variant_id))","CREATE INDEX tech_fault_context_variant ON tech_fault_contexts(variant_id)","CREATE TABLE tech_entries (id TEXT PRIMARY KEY, variant_id TEXT NOT NULL REFERENCES tech_variants(id),\n    kind TEXT NOT NULL CHECK(kind IN ('maintenance','measure','procedure','characteristic')),\n    title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', value TEXT, unit TEXT, conditions TEXT,\n    document_id TEXT NOT NULL REFERENCES tech_documents(id), page INTEGER CHECK(page IS NULL OR page > 0))","CREATE INDEX tech_entries_variant ON tech_entries(variant_id,kind)","CREATE TABLE tech_identifiers (variant_id TEXT NOT NULL REFERENCES tech_variants(id),\n    namespace TEXT NOT NULL, value TEXT NOT NULL, normalized_value TEXT NOT NULL,\n    PRIMARY KEY(variant_id,namespace,value))","CREATE INDEX tech_identifiers_lookup ON tech_identifiers(normalized_value)","CREATE TABLE tech_search_tokens (token TEXT NOT NULL, kind TEXT NOT NULL, entity_id TEXT NOT NULL,\n    PRIMARY KEY(token,kind,entity_id)) WITHOUT ROWID","CREATE INDEX tech_search_entity ON tech_search_tokens(kind,entity_id)","CREATE TABLE tech_private (user_id TEXT NOT NULL REFERENCES auth_users(id),\n    enterprise_id TEXT NOT NULL REFERENCES enterprises(id), kind TEXT NOT NULL CHECK(kind IN ('device','fault')),\n    entity_id TEXT NOT NULL, favorite INTEGER NOT NULL DEFAULT 0, note TEXT NOT NULL DEFAULT '', viewed_at TEXT,\n    PRIMARY KEY(user_id,enterprise_id,kind,entity_id))","CREATE TABLE tech_imports (dataset_id TEXT PRIMARY KEY, revision INTEGER NOT NULL, imported_at TEXT NOT NULL)","CREATE TABLE tech_import_ownership (table_name TEXT NOT NULL, entity_key TEXT NOT NULL, dataset_id TEXT NOT NULL REFERENCES tech_imports(dataset_id), PRIMARY KEY(table_name,entity_key))","CREATE TABLE installed_devices (id TEXT PRIMARY KEY, enterprise_id TEXT NOT NULL REFERENCES enterprises(id),\n    client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,\n    chantier_id TEXT REFERENCES chantiers(id) ON DELETE CASCADE,\n    variant_id TEXT NOT NULL REFERENCES tech_variants(id), serial_number TEXT, installed_at TEXT, notes TEXT)","CREATE TRIGGER installed_device_insert BEFORE INSERT ON installed_devices\n    WHEN NOT EXISTS(SELECT 1 FROM clients WHERE id=NEW.client_id AND enterprise_id=NEW.enterprise_id)\n    OR (NEW.chantier_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM chantiers WHERE id=NEW.chantier_id\n    AND enterprise_id=NEW.enterprise_id AND client_id=NEW.client_id))\n    BEGIN SELECT RAISE(ABORT,'Appareil install\xe9 hors entreprise ou client'); END","CREATE TRIGGER installed_device_update BEFORE UPDATE ON installed_devices\n    WHEN NEW.enterprise_id IS NOT OLD.enterprise_id\n    OR NOT EXISTS(SELECT 1 FROM clients WHERE id=NEW.client_id AND enterprise_id=NEW.enterprise_id)\n    OR (NEW.chantier_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM chantiers WHERE id=NEW.chantier_id\n    AND enterprise_id=NEW.enterprise_id AND client_id=NEW.client_id))\n    BEGIN SELECT RAISE(ABORT,'Appareil install\xe9 hors entreprise ou client'); END","CREATE TRIGGER tech_fault_context_guard BEFORE INSERT ON tech_fault_contexts\n    WHEN NOT EXISTS(SELECT 1 FROM tech_variants v JOIN tech_models m ON m.id=v.model_id\n      JOIN tech_ranges r ON r.id=m.range_id JOIN tech_faults f ON f.id=NEW.fault_id\n      WHERE v.id=NEW.variant_id AND r.manufacturer_id=f.manufacturer_id)\n    BEGIN SELECT RAISE(ABORT,'Contexte constructeur incoh\xe9rent'); END","CREATE TRIGGER tech_fault_source_guard BEFORE INSERT ON tech_faults\n    WHEN NOT EXISTS(SELECT 1 FROM tech_documents d WHERE d.id=NEW.document_id AND d.manufacturer_id=NEW.manufacturer_id)\n    BEGIN SELECT RAISE(ABORT,'Source constructeur incoh\xe9rente'); END","CREATE TRIGGER installed_chantier_client_guard BEFORE UPDATE OF client_id ON chantiers\n    WHEN NEW.client_id IS NOT OLD.client_id AND EXISTS(SELECT 1 FROM installed_devices d WHERE d.chantier_id=OLD.id AND d.client_id<>NEW.client_id)\n    BEGIN SELECT RAISE(ABORT,'R\xe9associez les appareils install\xe9s avant de changer le client'); END","CREATE TRIGGER tech_variant_source_guard BEFORE INSERT ON tech_variants\n    WHEN NEW.source_document_id IS NULL OR NOT EXISTS(SELECT 1 FROM tech_models m JOIN tech_ranges r ON r.id=m.range_id\n    JOIN tech_documents d ON d.manufacturer_id=r.manufacturer_id WHERE m.id=NEW.model_id AND d.id=NEW.source_document_id)\n    BEGIN SELECT RAISE(ABORT,'Source de la fiche appareil incoh\xe9rente'); END","CREATE TRIGGER tech_entry_source_guard BEFORE INSERT ON tech_entries\n    WHEN NOT EXISTS(SELECT 1 FROM tech_variants v JOIN tech_models m ON m.id=v.model_id JOIN tech_ranges r ON r.id=m.range_id\n    JOIN tech_documents d ON d.manufacturer_id=r.manufacturer_id WHERE v.id=NEW.variant_id AND d.id=NEW.document_id)\n    BEGIN SELECT RAISE(ABORT,'Source de la valeur technique incoh\xe9rente'); END","CREATE TRIGGER tech_document_link_guard BEFORE INSERT ON tech_document_links\n    WHEN NOT EXISTS(SELECT 1 FROM tech_variants v JOIN tech_models m ON m.id=v.model_id JOIN tech_ranges r ON r.id=m.range_id\n    JOIN tech_documents d ON d.manufacturer_id=r.manufacturer_id WHERE v.id=NEW.variant_id AND d.id=NEW.document_id)\n    BEGIN SELECT RAISE(ABORT,'Document li\xe9 hors constructeur'); END","CREATE TRIGGER tech_private_target_guard BEFORE INSERT ON tech_private\n    WHEN (NEW.kind='device' AND NOT EXISTS(SELECT 1 FROM tech_variants WHERE id=NEW.entity_id))\n    OR (NEW.kind='fault' AND NOT EXISTS(SELECT 1 FROM tech_faults WHERE id=NEW.entity_id))\n    BEGIN SELECT RAISE(ABORT,'Favori ou note sans fiche'); END","CREATE TRIGGER tech_private_identity_guard BEFORE UPDATE ON tech_private\n    WHEN NEW.user_id IS NOT OLD.user_id OR NEW.enterprise_id IS NOT OLD.enterprise_id\n    OR NEW.kind IS NOT OLD.kind OR NEW.entity_id IS NOT OLD.entity_id\n    BEGIN SELECT RAISE(ABORT,'Identit\xe9 des donn\xe9es priv\xe9es non modifiable'); END","INSERT INTO tech_manufacturers VALUES ('chaffoteaux','Chaffoteaux')","INSERT INTO tech_manufacturers VALUES ('de_dietrich','De Dietrich')"],t.s)
